bpy.ops.object.select_all(action='SELECT')
bpy.ops.object.delete(use_global=False)

# Create 21 Landmark empties/spheres
spheres = []
for i in range(21):
    bpy.ops.mesh.primitive_uv_sphere_add(radius=0.03, location=(0, 0, 0))
    s = bpy.context.active_object
    s.name = f"Joint_{i}"
    spheres.append(s)

# Keyframe over 30 frames
for frame_idx, frame_pts in enumerate(motion_data):
    bpy.context.scene.frame_set(frame_idx + 1)
    pts_21x3 = np.array(frame_pts).reshape(21, 3)
    for joint_idx in range(21):
        x, y, z = pts_21x3[joint_idx]
        obj = spheres[joint_idx]
        obj.location = (x * 2.0, -z * 2.0, -y * 2.0)
        obj.keyframe_insert(data_path="location", index=-1)

bpy.context.scene.frame_start = 1
bpy.context.scene.frame_end = len(motion_data)
print("Animation loaded for 'Water Please'! Press Play (Spacebar) in Blender.")
